package edu.exam;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.util.*;import java.time.*;import java.math.*;
@Service @Transactional public class Portal {
 final Store db;final BCryptPasswordEncoder encoder;@Value("${exam.pass-percentage}") BigDecimal pass;
 Portal(Store d,BCryptPasswordEncoder e){db=d;encoder=e;}
 long me(){return Long.parseLong(SecurityContextHolder.getContext().getAuthentication().getName());}
 String role(){return SecurityContextHolder.getContext().getAuthentication().getAuthorities().iterator().next().getAuthority().substring(5);}
 void require(String r){if(!role().equals(r))throw new Failure(403,"This action requires "+r);}
 static long id(Object x){if(x==null)throw new Failure(400,"A required identifier is missing");return Long.parseLong(x.toString());}
 static String text(Map<String,Object> m,String k){Object v=m.get(k);if(v==null||v.toString().isBlank())throw new Failure(400,k+" is required");return v.toString().trim();}
 static BigDecimal positive(Map<String,Object> m,String k){var n=new BigDecimal(text(m,k));if(n.signum()<=0)throw new Failure(400,k+" must be positive");return n;}
 Map<String,Object> course(long c){var x=db.one("SELECT * FROM courses WHERE course_id=?",c);if(role().equals("FACULTY")&&id(x.get("faculty_id"))!=me())throw new Failure(403,"Course belongs to another faculty member");return x;}
 Map<String,Object> exam(long e){var x=db.one("SELECT * FROM exams WHERE exam_id=?",e);course(id(x.get("course_id")));return x;}
 void draft(Map<String,Object> e){if(!e.get("status").equals("DRAFT"))throw new Failure(409,"Only draft exams can be edited");}
 Map<String,Object> safe(long u){return db.one("SELECT user_id,full_name,email,role,is_active FROM users WHERE user_id=?",u);}
 public Object users(String search,int page,int size){require("ADMIN");if(page<0||size<1||size>100)throw new Failure(400,"Invalid pagination");return db.rows("SELECT user_id,full_name,email,role,is_active FROM users WHERE full_name LIKE ? OR email LIKE ? ORDER BY user_id DESC LIMIT ? OFFSET ?","%"+search+"%","%"+search+"%",size,page*size);}
 public Object users(){return users("",0,100);}
 public Object user(Long u,Map<String,Object> m){require("ADMIN");String name=text(m,"full_name"),email=text(m,"email").toLowerCase(),r=text(m,"role");if(!email.matches("[^ @]+@[^ @]+\\.[^ @]+")||!Set.of("ADMIN","FACULTY","STUDENT").contains(r))throw new Failure(400,"Invalid email or role");if(u==null){String pw=text(m,"password");if(pw.length()<8)throw new Failure(400,"Password requires 8 characters");u=db.insert("INSERT INTO users(full_name,email,role,password_hash) VALUES(?,?,?,?)",name,email,r,encoder.encode(pw));}else{var old=safe(u);if(!old.get("role").equals(r))throw new Failure(409,"Account roles cannot be changed after creation");db.exec("UPDATE users SET full_name=?,email=? WHERE user_id=?",name,email,u);}return safe(u);}
 public Object deactivate(long u){require("ADMIN");if(u==me())throw new Failure(409,"Cannot deactivate your current account");db.exec("UPDATE users SET is_active=0 WHERE user_id=?",u);return safe(u);}
 public Object courses(){return switch(role()){case "ADMIN"->db.rows("SELECT c.*,u.full_name faculty_name FROM courses c JOIN users u ON u.user_id=c.faculty_id");case "FACULTY"->db.rows("SELECT * FROM courses WHERE faculty_id=?",me());default->db.rows("SELECT c.* FROM courses c JOIN enrollments n ON n.course_id=c.course_id WHERE n.student_id=?",me());};}
 public Object saveCourse(Long c,Map<String,Object> m){require("ADMIN");long f=id(m.get("faculty_id"));if(!safe(f).get("role").equals("FACULTY"))throw new Failure(400,"Choose a faculty account");String code=text(m,"course_code"),name=text(m,"course_name");if(c==null)c=db.insert("INSERT INTO courses(course_code,course_name,description,faculty_id) VALUES(?,?,?,?)",code,name,m.getOrDefault("description",""),f);else{course(c);db.exec("UPDATE courses SET course_code=?,course_name=?,description=?,faculty_id=? WHERE course_id=?",code,name,m.getOrDefault("description",""),f,c);}return course(c);}
 public Object enrollments(Long c){if(c!=null)course(c);if(role().equals("STUDENT"))return db.rows("SELECT * FROM enrollments WHERE student_id=?",me());return role().equals("ADMIN")?db.rows("SELECT n.*,u.full_name,c.course_name FROM enrollments n JOIN users u ON u.user_id=n.student_id JOIN courses c ON c.course_id=n.course_id"):db.rows("SELECT n.*,u.full_name FROM enrollments n JOIN users u ON u.user_id=n.student_id WHERE n.course_id=?",c);}
 public Object enroll(Map<String,Object> m){require("ADMIN");long s=id(m.get("student_id")),c=id(m.get("course_id"));if(!safe(s).get("role").equals("STUDENT"))throw new Failure(400,"Only students may enroll");db.exec("INSERT INTO enrollments(student_id,course_id) VALUES(?,?)",s,c);return Map.of("message","Student enrolled");}
 public void remove(long s,long c){require("ADMIN");if(!db.rows("SELECT a.attempt_id FROM attempts a JOIN exams e ON e.exam_id=a.exam_id WHERE a.student_id=? AND e.course_id=?",s,c).isEmpty())throw new Failure(409,"Enrollment has historical attempts");db.exec("DELETE FROM enrollments WHERE student_id=? AND course_id=?",s,c);}
 public Object exams(){return switch(role()){case "ADMIN"->db.rows("SELECT * FROM exams");case "FACULTY"->db.rows("SELECT e.* FROM exams e JOIN courses c ON c.course_id=e.course_id WHERE c.faculty_id=?",me());default->db.rows("SELECT e.*,a.attempt_id,a.status attempt_status FROM exams e JOIN enrollments n ON n.course_id=e.course_id LEFT JOIN attempts a ON a.exam_id=e.exam_id AND a.student_id=n.student_id WHERE n.student_id=? AND e.status<>'DRAFT'",me());};}
 public Object saveExam(Long e,Map<String,Object> m){require("FACULTY");long c=id(m.get("course_id"));course(c);if(e!=null)draft(exam(e));var start=LocalDateTime.parse(text(m,"start_time"));var end=LocalDateTime.parse(text(m,"end_time"));if(!end.isAfter(start))throw new Failure(400,"End must follow start");int duration=positive(m,"duration_minutes").intValueExact();var marks=positive(m,"total_marks");if(e==null)e=db.insert("INSERT INTO exams(course_id,created_by,exam_title,description,start_time,end_time,duration_minutes,total_marks,pass_percentage) VALUES(?,?,?,?,?,?,?,?,?)",c,me(),text(m,"exam_title"),m.getOrDefault("description",""),start,end,duration,marks,pass);else db.exec("UPDATE exams SET course_id=?,exam_title=?,description=?,start_time=?,end_time=?,duration_minutes=?,total_marks=? WHERE exam_id=?",c,text(m,"exam_title"),m.getOrDefault("description",""),start,end,duration,marks,e);return exam(e);}
 public Object details(long e){var x=exam(e);x.put("questions",questions(e,true));return x;}
 List<Map<String,Object>> questions(long e,boolean reveal){var qs=db.rows("SELECT * FROM questions WHERE exam_id=? ORDER BY question_order",e);for(var q:qs)q.put("options",db.rows("SELECT option_id,option_label,option_text"+(reveal?",is_correct":"")+" FROM question_options WHERE question_id=? ORDER BY option_label",q.get("question_id")));return qs;}
 public Object question(long e,Long q,Map<String,Object> m){require("FACULTY");draft(exam(e));String t=text(m,"question_text");var marks=positive(m,"marks");var opts=(List<Map<String,Object>>)m.get("options");if(opts==null||opts.size()!=4||opts.stream().filter(o->Boolean.TRUE.equals(o.get("is_correct"))).count()!=1)throw new Failure(400,"Provide four options and exactly one correct answer");opts.forEach(o->text(o,"option_text"));if(q==null)q=db.insert("INSERT INTO questions(exam_id,question_text,marks,question_order) SELECT ?,?,?,COALESCE(MAX(question_order),0)+1 FROM questions WHERE exam_id=?",e,t,marks,e);else{db.one("SELECT question_id FROM questions WHERE question_id=? AND exam_id=?",q,e);db.exec("UPDATE questions SET question_text=?,marks=? WHERE question_id=?",t,marks,q);db.exec("DELETE FROM question_options WHERE question_id=?",q);}for(int i=0;i<4;i++)db.exec("INSERT INTO question_options(question_id,option_label,option_text,is_correct) VALUES(?,?,?,?)",q,"ABCD".substring(i,i+1),text(opts.get(i),"option_text"),Boolean.TRUE.equals(opts.get(i).get("is_correct")));return details(e);}
 public void deleteQuestion(long e,long q){require("FACULTY");draft(exam(e));db.exec("DELETE FROM questions WHERE question_id=? AND exam_id=?",q,e);}
 public Object transition(long e,boolean publish){require("FACULTY");var x=exam(e);if(publish){draft(x);var qs=questions(e,true);var sum=qs.stream().map(q->new BigDecimal(q.get("marks").toString())).reduce(BigDecimal.ZERO,BigDecimal::add);if(qs.isEmpty()||sum.compareTo(new BigDecimal(x.get("total_marks").toString()))!=0)throw new Failure(400,"Question marks must equal exam total");}else if(!x.get("status").equals("PUBLISHED"))throw new Failure(409,"Only published exams may close");db.exec("UPDATE exams SET status=? WHERE exam_id=?",publish?"PUBLISHED":"CLOSED",e);return exam(e);}
 LocalDateTime time(Object v){return v instanceof java.sql.Timestamp t?t.toLocalDateTime():LocalDateTime.parse(v.toString().replace(' ','T'));}
 public Object start(long e){require("STUDENT");var x=db.one("SELECT e.* FROM exams e JOIN enrollments n ON n.course_id=e.course_id WHERE e.exam_id=? AND n.student_id=?",e,me());var now=LocalDateTime.now(ZoneOffset.UTC);if(!x.get("status").equals("PUBLISHED")||now.isBefore(time(x.get("start_time")))||!now.isBefore(time(x.get("end_time"))))throw new Failure(409,"Exam is not open");long a=db.insert("INSERT INTO attempts(exam_id,student_id) VALUES(?,?)",e,me());return attempt(a,false);}
 Map<String,Object> owned(long a){require("STUDENT");return db.one("SELECT a.*,e.end_time,e.duration_minutes,e.exam_title,e.total_marks FROM attempts a JOIN exams e ON e.exam_id=a.exam_id WHERE a.attempt_id=? AND a.student_id=? FOR UPDATE",a,me());}
 LocalDateTime deadline(Map<String,Object> a){var d=time(a.get("started_at")).plusMinutes(id(a.get("duration_minutes")));var end=time(a.get("end_time"));return d.isBefore(end)?d:end;}
 public Object attempt(long id,boolean result){var a=owned(id);boolean done=a.get("status").equals("SUBMITTED");if(result&&!done)throw new Failure(409,"Result not released");a.put("deadline",deadline(a).toString()+"Z");a.put("server_now",Instant.now().toString());a.put("questions",questions(Portal.id(a.get("exam_id")),done));a.put("responses",db.rows("SELECT question_id,selected_option_id FROM responses WHERE attempt_id=?",id));return a;}
 public Object respond(long id,Map<String,Object> m,boolean submit){var a=owned(id);if(!a.get("status").equals("IN_PROGRESS"))throw new Failure(409,"Attempt already submitted");if(LocalDateTime.now(ZoneOffset.UTC).isAfter(deadline(a)))throw new Failure(409,"Submission deadline has passed");var rs=(List<Map<String,Object>>)m.getOrDefault("responses",List.of());for(var r:rs){long q=Portal.id(r.get("question_id"));db.one("SELECT question_id FROM questions WHERE question_id=? AND exam_id=?",q,a.get("exam_id"));Object o=r.get("selected_option_id");if(o!=null)db.one("SELECT option_id FROM question_options WHERE option_id=? AND question_id=?",o,q);db.exec("INSERT INTO responses(attempt_id,exam_id,question_id,selected_option_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE selected_option_id=VALUES(selected_option_id)",id,a.get("exam_id"),q,o);}if(submit){var score=db.one("SELECT COALESCE(SUM(CASE WHEN o.is_correct=1 THEN q.marks ELSE 0 END),0) score FROM responses r JOIN questions q ON q.question_id=r.question_id LEFT JOIN question_options o ON o.option_id=r.selected_option_id WHERE r.attempt_id=?",id).get("score");db.exec("UPDATE attempts SET status='SUBMITTED',submitted_at=UTC_TIMESTAMP(),score=? WHERE attempt_id=?",score,id);}return attempt(id,false);}
 public Object results(Long e){if(role().equals("STUDENT"))return db.rows("SELECT a.*,e.exam_title,e.total_marks FROM attempts a JOIN exams e ON e.exam_id=a.exam_id WHERE a.student_id=? AND a.status='SUBMITTED'",me());if(e!=null)exam(e);return db.rows("SELECT a.*,u.full_name,e.exam_title,e.total_marks FROM attempts a JOIN users u ON u.user_id=a.student_id JOIN exams e ON e.exam_id=a.exam_id JOIN courses c ON c.course_id=e.course_id WHERE a.status='SUBMITTED'"+(role().equals("FACULTY")?" AND c.faculty_id="+me():"")+(e!=null?" AND e.exam_id="+e:""));}
 public Object report(boolean byCourse){if(role().equals("STUDENT"))throw new Failure(403,"Reports require faculty or admin");String key=byCourse?"c.course_id,c.course_name":"e.exam_id,e.exam_title";return db.rows("SELECT "+key+",COUNT(a.attempt_id) submitted_attempts,COALESCE(ROUND(AVG(a.score),2),0) average_score,COALESCE(MAX(a.score),0) highest_score,COALESCE(ROUND(100.0*SUM(CASE WHEN a.score*100/e.total_marks>=e.pass_percentage THEN 1 ELSE 0 END)/NULLIF(COUNT(a.attempt_id),0),2),0) pass_percentage FROM courses c LEFT JOIN exams e ON e.course_id=c.course_id LEFT JOIN attempts a ON a.exam_id=e.exam_id AND a.status='SUBMITTED'"+(role().equals("FACULTY")?" WHERE c.faculty_id="+me():"")+" GROUP BY "+key);}
}
